  const frozen = (h: RawHolder) => h.exists && (h.flags & 0x01) !== 0

  check(approved(a!), 'A is approved')
  check(a!.amount === 500n, `A holds 500 (actual ${a!.amount})`)
  check(!frozen(a!), 'A is NOT frozen')

