import { readFileSync } from 'node:fs'
import { Client, MPTokenAuthorizeFlags, Wallet } from 'xrpl'
import { InMemoryBanRegistry, MptIssuer, submitAndConfirm } from '../src'
const w = JSON.parse(readFileSync('scratch/aborted-run-wallets.json', 'utf8'))
const id: string = w.issuanceId
if (id === JSON.parse(readFileSync('result.json', 'utf8')).issuanceId) throw new Error('refusing to touch the demo issuance')
const I = Wallet.fromSeed(process.env.XRPL_ISSUER_SEED!)
const c = new Client('wss://s.altnet.rippletest.net:51233')
;(async () => {
  await c.connect()
  const iss = await MptIssuer.load({ client: c, issuerWallet: I, issuanceId: id, banRegistry: new InMemoryBanRegistry() })
  for (const k of ['A', 'B', 'C']) {
    const h = Wallet.fromSeed(w.holders[k].seed)
    const s = await iss.getHolder(h.classicAddress)
    if (s.balance > 0n) console.log(k, 'clawback', s.balance, (await iss.clawback(h.classicAddress, s.balance)).hash)
    if (s.optedIn) console.log(k, 'delete MPToken', (await submitAndConfirm(c, h, { TransactionType: 'MPTokenAuthorize', Account: h.classicAddress, MPTokenIssuanceID: id, Flags: MPTokenAuthorizeFlags.tfMPTUnauthorize })).hash)
  }
  console.log('destroy', (await submitAndConfirm(c, I, { TransactionType: 'MPTokenIssuanceDestroy', Account: I.classicAddress, MPTokenIssuanceID: id })).hash)
  const objs = await c.request({ command: 'account_objects', account: I.classicAddress, type: 'mpt_issuance' })
  console.log('issuer issuances now:', objs.result.account_objects.map((o: any) => o.mpt_issuance_id ?? o.index))
  const ai = await c.request({ command: 'account_info', account: I.classicAddress })
  console.log('issuer XRP:', Number(ai.result.account_data.Balance) / 1e6)
  await c.disconnect()
})()
EOF
